		"has-data-[icon=inline-end]:pr-2", "has-data-[icon=inline-end]:pe-2",
		"has-data-[icon=inline-start]:pl-2", "has-data-[icon=inline-start]:ps-2",
		"py-2 pr-2 pl-2.5", "py-2 ps-2.5 pe-2",
	).Replace(c)
