func subMenu(items []string) h.Node {
	return sidebar.MenuSub(h.Map(items, func(t string) h.Node {
		return sidebar.MenuSubItem(sidebar.MenuSubButton(lib.AsChild, h.A(h.Href("#"), h.Span(t))))
