// MenuAction is sidebar-menu-action.
func MenuAction() h.Node {
	return sidebar.Provider(
		sidebar.Sidebar(
			sidebar.Content(
				sidebar.Group(
					sidebar.GroupLabel("Projects"),
					sidebar.GroupContent(
						sidebar.Menu(h.Map(projects, func(p link) h.Node {
							return sidebar.MenuItem(
