// MenuSub is sidebar-menu-sub.
func MenuSub() h.Node {
	return sidebar.Provider(
		sidebar.Sidebar(
			sidebar.Content(
				sidebar.Group(
					sidebar.GroupContent(
						sidebar.Menu(h.Map(docs, func(s section) h.Node {
							return sidebar.MenuItem(
								sidebar.MenuButton(lib.AsChild, h.A(h.Href("#"), h.Span(s.title))),
								subMenu(s.items),
							)
						})),
					),
				),
			),
		),
