func BarNegative(r *http.Request) h.Node {
	config := chart.Config{{Key: "visitors", Label: "Visitors"}}
	cells := make([]*chart.Node, 0, len(dataBarNegative))
	for _, row := range dataBarNegative {
		fill := "var(--chart-2)"
