form-formisch-array:
import (
	"encoding/json"
	"github.com/alexisbcz/components/ui/button"
	"github.com/alexisbcz/components/ui/card"
	"github.com/alexisbcz/components/ui/field"
	"github.com/alexisbcz/components/ui/input"
	"github.com/alexisbcz/components/ui/input-group"
	"github.com/alexisbcz/icons/lucide"
	h "github.com/alexisbcz/libhtml"
	"strconv"
)

func Example() h.Node { return Array(formisch) }

// Array is form-{rhf,tanstack,formisch}-array.
func Array(l Lib) h.Node {
	name := "form-" + string(l) + "-array"
	n := 2
	if l == tanstack {
		n = 1
	}
	items := field.Group(h.Class("gap-4"))
	for i := 0; i < n; i++ {
		items.Children(emailItem(l, name, i, n > 1))
	}
	items.Children(button.Button(h.Type("button"), button.VariantOutline, button.SizeSm, "Add Email Address"))
	return h.Group(
		card.Card(h.Class("w-full sm:max-w-md"),
			header("Contact Emails", "Manage your contact email addresses.", h.Class("border-b")),
			card.Content(formTag(l, name,
				field.Set(h.Class("gap-4"),
					field.Legend(field.LegendLabel, "Email Addresses"),
					field.Description("Add up to 5 email addresses where we can contact you."),
					items,
				),
			)),
			card.Footer(h.Class("border-t"),
				field.Field(field.Horizontal,
					button.Button(h.Type("button"), button.VariantOutline, "Reset"),
					button.Button(h.Type("submit"), h.FormAttr(name), "Save"),
				),
			),
		),
		// The item and remove-button prototypes the client clones.
		h.Template(h.Data("parity-ignore", ""), h.Data("form-example", name),
			h.Div(h.Data("proto", "item"), emailItem(l, name, 0, false)),
			h.Div(h.Data("proto", "remove"), emailRemove(0)),
		),
	)
}

// Lib is the form library an example uses upstream.
type Lib string

const (
	rhf      Lib = "rhf"
	tanstack Lib = "tanstack"
	formisch Lib = "formisch"
)

// emailItem is one email of the array examples.
func emailItem(l Lib, name string, index int, removable bool) *field.Builder {
	group := inputgroup.InputGroup(
		inputgroup.Input(
			h.Name(emailName(l, index)),
			h.Value(""),
			h.ID(name+"-email-"+strconv.Itoa(index)),
			ariaInvalid(),
			h.Placeholder("name@example.com"),
			h.Type("email"),
			h.AutoComplete("email"),
		),
	)
	if removable {
		group.Children(emailRemove(index))
	}
	return field.Field(field.Horizontal, dataInvalid(), field.Content(group))
}

// Input is form-{rhf,tanstack,formisch}-input.
func Input(l Lib) h.Node {
	name := "form-" + string(l) + "-input"
	return with(name, card.Card(h.Class("w-full sm:max-w-md"),
		header("Profile Settings", "Update your profile information below."),
		card.Content(
			formTag(l, name,
				field.Group(
					field.Field(dataInvalid(),
						field.Label(h.For(name+"-username"), "Username"),
						input.Input(
							h.Name(fieldName(l, "username")),
							h.Value(""),
							h.ID(name+"-username"),
							ariaInvalid(),
							h.Placeholder("shadcn"),
							h.AutoComplete("username"),
						),
						field.Description("This is your public display name. Must be between 3 and 10 characters. Must only contain letters, numbers, and underscores."),
					),
				),
			),
		),
		footer(name, "Save"),
	))
}

// with renders an example's root followed by its marker.
func with(name string, root h.Node) h.Node { return h.Group(root, marker(name)) }

// marker is the example's inert template: the examples' module finds the
// example by it (its previous sibling is the example's root).
func marker(name string) h.Node {
	return h.Template(h.Data("parity-ignore", ""), h.Data("form-example", name))
}

func header(title, description string, children ...any) h.Node {
	return card.Header(append(children, card.Title(title), card.Description(description))...)
}

// formTag is the <form>: Formisch's <Form> adds noValidate.
func formTag(l Lib, id string, children ...any) *h.Element {
	f := h.Form(h.ID(id))
	if l == formisch {
		f.Bool("novalidate", true)
	}
	return f.Children(children...)
}

// invalid renders React's data-invalid={false} / aria-invalid={false}.
func dataInvalid() h.Prop { return h.Data("invalid", "false") }

// fieldName is the name attribute of a field's control: Formisch names
// fields by their JSON path.
func fieldName(l Lib, path ...any) string {
	if l == formisch {
		b, _ := json.Marshal(path)
		return string(b)
	}
	s := ""
	for i, p := range path {
		if i > 0 {
			s += "."
		}
		switch v := p.(type) {
		case string:
			s += v
		case int:
			b, _ := json.Marshal(v)
			s += string(b)
		}
	}
	return s
}

func ariaInvalid() h.Prop { return h.Aria("invalid", "false") }

// footer is the examples' CardFooter: Reset and Submit.
