func Example() h.Node { return NextComplex(NextComplexDefaults, false) }

// NextComplex is form-next-complex rendered for a state (see NextDemo for
// how the parity page submits).
func NextComplex(state NextComplexState, pending bool) h.Node {
	o := complexOpts{next: true, formID: "subscription-form", withName: true,
		idOf:    func(s string) string { return s },
		values:  state.Values,
		errors:  state.Errors,
		pending: pending,
	}
	submit := button.Button(h.Type("submit"), h.FormAttr(o.formID))
	if pending {
		submit.Disabled(true)
		submit.Children(spinner.Spinner())
	}
	submit.Children("Save Preferences")
	return with("form-next-complex", card.Card(h.Class("w-full max-w-sm"),
		card.Content(h.Form(h.ID(o.formID), subscriptionForm(o))),
		card.Footer(field.Field(field.Horizontal, h.Class("justify-end"), submit)),
	))
}

// NextComplexState is form-next-complex's FormState.
type NextComplexState struct {
	Values  NextComplexValues
	Errors  map[string][]string
	Success bool
}

// NextComplexValues are form-next-complex's fields.
type NextComplexValues = complexValues

// complexValues are the subscription form's values.
type complexValues struct {
	Plan               string
	BillingPeriod      string
	Addons             []string
	EmailNotifications bool
}

// complexOpts describes the variants of the subscription form.
type complexOpts struct {
	lib      Lib
	next     bool // form-next-complex (uncontrolled, React's useActionState)
	formID   string
	idOf     func(string) string // element ids by field / option
	values   complexValues
	errors   map[string][]string
	pending  bool
	withName bool
}

// Lib is the form library an example uses upstream.
type Lib string

func (o complexOpts) invalid(f string) h.Prop {
	if len(o.errors[f]) > 0 {
		return h.Data("invalid", "true")
	}
	return dataInvalid()
}

// invalid renders React's data-invalid={false} / aria-invalid={false}.
func dataInvalid() h.Prop { return h.Data("invalid", "false") }

func (o complexOpts) ariaInvalid(f string) h.Prop {
	if len(o.errors[f]) > 0 {
		return h.Aria("invalid", "true")
	}
	return ariaInvalid()
}

func ariaInvalid() h.Prop { return h.Aria("invalid", "false") }

func (o complexOpts) errorOf(f string) h.Node {
	if len(o.errors[f]) == 0 {
		return nil
	}
	if o.next {
		return field.Error(o.errors[f][0])
	}
	return field.Errors(o.errors[f])
}

// with renders an example's root followed by its marker.
func with(name string, root h.Node) h.Node { return h.Group(root, marker(name)) }

// marker is the example's inert template: the examples' module finds the
// example by it (its previous sibling is the example's root).
func marker(name string) h.Node {
	return h.Template(h.Data("parity-ignore", ""), h.Data("form-example", name))
}

// subscriptionForm renders form-{rhf,tanstack,formisch,next}-complex's
// fields. TanStack's and Next's variants mark the plan's items invalid and
// not the set, and leave the select trigger without aria-invalid.
func subscriptionForm(o complexOpts) h.Node {
	tanstackLike := o.lib == tanstack || o.next
	group := radiogroup.RadioGroup(radiogroup.Value(o.values.Plan))
	if o.withName {
		group.Name("plan")
	}
	if !tanstackLike || o.next {
		group.Children(o.ariaInvalid("plan"))
	}
	if o.pending {
		group.Disabled(true)
	}
	for _, p := range complexPlans {
		f := field.Field(field.Horizontal,
			field.Content(field.Title(p.title), field.Description(p.description)),
		)
		item := radiogroup.Item(radiogroup.Value(p.id), h.ID(o.idOf(p.id)))
		if tanstackLike && !o.next {
			f.Children(o.invalid("plan"))
			item.Children(o.ariaInvalid("plan"))
		}
		f.Children(item)
		group.Children(field.Label(h.For(o.idOf(p.id)), f))
	}
	planSet := field.Set()
	if !tanstackLike || o.next {
		planSet.Children(o.invalid("plan"))
	}
	legend := field.Legend(field.LegendLabel, "Subscription Plan")
	if tanstackLike {
		legend = field.Legend("Subscription Plan")
	}
	planSet.Children(legend, field.Description("Choose your subscription plan."), group, o.errorOf("plan"))

	trigger := selectui.Trigger(h.ID(o.idOf("billingPeriod")), selectui.Value(selectui.Placeholder("Select")))
	if !tanstackLike {
		trigger.Children(o.ariaInvalid("billingPeriod"))
	}
	if o.pending {
		trigger.Disabled(true)
	}
	sel := selectui.Select(selectui.DefaultValue(o.values.BillingPeriod),
		trigger,
		selectui.Content(
			selectui.Item(selectui.ItemValue("monthly"), "Monthly"),
			selectui.Item(selectui.ItemValue("yearly"), "Yearly"),
		),
	)
	if o.withName {
		sel.Name("billingPeriod")
	}

	boxes := field.Group(h.Data("slot", "checkbox-group"))
	for _, a := range addons {
		cb := checkbox.Checkbox(h.ID(o.idOf(a.id)), o.ariaInvalid("addons"), checkbox.Checked(contains(o.values.Addons, a.id)))
		if o.withName {
			cb.Name("addons")
		}
		if o.next {
			cb.Value(a.id)
		}
		if o.pending {
			cb.Disabled(true)
		}
		boxes.Children(field.Field(field.Horizontal, o.invalid("addons"),
			cb,
			field.Content(
				field.Label(h.For(o.idOf(a.id)), a.title),
				field.Description(a.description),
			),
		))
	}

	sw := switchui.Switch(h.ID(o.idOf("emailNotifications")), o.ariaInvalid("emailNotifications"), switchui.Checked(o.values.EmailNotifications))
	if o.withName {
		sw.Name("emailNotifications")
	}
	if o.pending {
		sw.Disabled(true)
	}
	notifications := field.Field(field.Horizontal,
		field.Content(
			field.Label(h.For(o.idOf("emailNotifications")), "Email Notifications"),
			field.Description("Receive email updates about your subscription"),
		),
		sw,
		o.errorOf("emailNotifications"),
	)
	if !o.next {
		notifications.Children(o.invalid("emailNotifications"))
	}

	return field.Group(
		planSet,
		field.Separator(),
		field.Field(o.invalid("billingPeriod"),
			field.Label(h.For(o.idOf("billingPeriod")), "Billing Period"),
			sel,
			field.Description("Choose how often you want to be billed."),
			o.errorOf("billingPeriod"),
		),
		field.Separator(),
		field.Set(
			field.Legend("Add-ons"),
			field.Description("Select additional features you'd like to include."),
			boxes,
			o.errorOf("addons"),
		),
		field.Separator(),
		notifications,
	)
}

const (
	rhf      Lib = "rhf"
	tanstack Lib = "tanstack"
	formisch Lib = "formisch"
)

// RadioGroup is form-{rhf,tanstack,formisch}-radiogroup.
func RadioGroup(l Lib) h.Node {
	name := "form-" + string(l) + "-radiogroup"
	group := radiogroup.RadioGroup(radiogroup.Value(""))
	if l != formisch {
		group.Name("plan")
	}
	if l != tanstack {
		group.Children(ariaInvalid())
	}
	for _, p := range plans {
		group.Children(field.Label(h.For(name+"-"+p.id),
			field.Field(field.Horizontal, dataInvalid(),
				field.Content(
					field.Title(p.title),
					field.Description(p.description),
				),
				radiogroup.Item(radiogroup.Value(p.id), h.ID(name+"-"+p.id), ariaInvalid()),
			),
		))
	}
	set := field.Set(
		field.Legend("Plan"),
		field.Description("You can upgrade or downgrade your plan at any time."),
		group,
	)
	if l != tanstack {
		set = field.Set(dataInvalid(),
			field.Legend("Plan"),
			field.Description("You can upgrade or downgrade your plan at any time."),
			group,
		)
	}
	return with(name, card.Card(h.Class("w-full sm:max-w-md"),
