							h.Name(fieldName(l, "about")),
							h.ID(name+"-about"),
							ariaInvalid(),
							h.Placeholder("I'm a software engineer..."),
							h.Class("min-h-[120px]"),
						),
						field.Description("Tell us more about yourself. This will be used to help us personalize your experience."),
					),
				),
			),
		),
		footer(name, "Save"),
	))
