							h.Type("password"),
							h.Placeholder("Enter your password"),
							ariaInvalid(),
							h.AutoComplete("new-password"),
						),
						inputgroup.Addon(inputgroup.AlignInlineEnd, lucide.Check(h.Class("text-muted-foreground"))),
					),
					h.Div(h.Class("space-y-2"),
