	"github.com/alexisbcz/icons/lucide"
	h "github.com/alexisbcz/libhtml"
)

func Example() h.Node { return currencySelect(true) }

// currencySelect is button-group-select; the radix docs version wraps the
// items in a SelectGroup.
func currencySelect(grouped bool) h.Node {
	currencies := []struct{ value, label string }{
		{"$", "US Dollar"},
		{"€", "Euro"},
		{"£", "British Pound"},
	}
	var opts []any
	for _, c := range currencies {
		opts = append(opts, selectui.Item(selectui.ItemValue(c.value),
			c.value, " ", h.Span(h.Class("text-muted-foreground"), c.label),
		))
	}
	items := append([]any{h.Class("min-w-24")}, opts...)
	if grouped {
		items = []any{h.Class("min-w-24"), selectui.Group(opts...)}
	}
	return buttongroup.ButtonGroup(
		buttongroup.ButtonGroup(
			selectui.Select(selectui.DefaultValue("$"),
				selectui.Trigger(h.Class("font-mono"), h.Data("example-currency", ""), "$"),
				selectui.Content(items...),
			),
			input.Input(h.Placeholder("10.00"), h.Attr("pattern", "[0-9]*")),
		),
		buttongroup.ButtonGroup(
			button.Button(h.Aria("label", "Send"), button.SizeIcon, button.VariantOutline, lucide.ArrowRight()),
		),
	)
}

func Select() h.Node { return currencySelect(false) }

func Input() h.Node {
	return buttongroup.ButtonGroup(
		input.Input(h.Placeholder("Search...")),
		button.Button(button.VariantOutline, h.Aria("label", "Search"), lucide.Search()),
	)
}

