func novaTable(t dtText) h.Node {
	pick := func(en, rtl string) string {
		if t.rtl {
			return rtl
		}
		return en
	}
	body := table.Body()
	ids := make([]string, 0, len(Payments))
	for _, p := range Payments {
		status := p.Status
