	{"m5gr84i9", 316, "success", "ken99@example.com"},
	{"3u1reuv4", 242, "success", "Abe45@example.com"},
	{"derv1ws0", 837, "processing", "Monserrat44@example.com"},
	{"5kma53ae", 874, "success", "Silas22@example.com"},
	{"bhqecj4p", 721, "failed", "carmella@example.com"},
}

// Payment is a row of the demo.
type Payment struct {
	ID     string
	Amount float64
	Status string
	Email  string
}

func novaRowActions(t dtText) h.Node {
	content := []any{dm.AlignEnd, h.Class("w-40"),
		dm.Group(
			dm.Label(t.actions),
			dm.Item(t.copyID),
		),
	}
	if t.rtl {
		content = append(content, h.Data("lang", "ar"), dm.Separator())
	}
	content = append(content, dm.Group(
		dm.Item(t.viewCustomer),
		dm.Item(t.viewDetails),
	))
	return dm.DropdownMenu(
		dm.Trigger(lib.AsChild,
			button.Button(button.VariantGhost, button.SizeIconXs,
				h.Span(h.Class("sr-only"), t.openMenu),
				lucide.Ellipsis(),
			),
		),
		dm.Content(content...),
	)
