const animatedItemClass = "data-active:animate-in data-active:fade-in-0 data-active:slide-in-from-bottom-2 data-active:duration-300 motion-reduce:animate-none"

func nodes(ns []h.Node) []any {
	out := make([]any, len(ns))
	for i, n := range ns {
