func navUser(u user, compact bool, align dm.Align) h.Node {
	cls := "data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground"
	if compact {
		cls += " md:h-8 md:p-0"
	}
	return sidebar.Menu(
