							userAvatar(u),
							userText(u),
						),
					),
					dm.Separator(),
					dm.Group(dm.Item(lucide.Sparkles(), "Upgrade to Pro")),
					dm.Separator(),
					dm.Group(
						dm.Item(lucide.BadgeCheck(), "Account"),
						dm.Item(lucide.CreditCard(), "Billing"),
						dm.Item(lucide.Bell(), "Notifications"),
					),
					dm.Separator(),
					dm.Item(lucide.LogOut(), "Log out"),
				),
			),
		),
	)
}

