// className, style or icons).
func plainToaster() h.Node {
	el := sonner.Toaster(sonner.ThemeLight, sonner.SonnerIcons, sonner.PositionBottomLeft,
		sonner.ToastOptions(map[string]any{"className": "ml-[160px]"}),
